<?php
declare(strict_types=1);$pageTitle='My Children Records';require_once __DIR__.'/../includes/header.php';require_once __DIR__.'/_helpers.php';require_once __DIR__.'/_listing.php';require_permission('member.children.view');$mid=current_member_id();$tab=(string)($_GET['tab']??'baptism');$tabs=['baptism'=>'Baptism Register','sunday'=>'Sunday School','youth'=>'Youth Registry'];if(!isset($tabs[$tab]))$tab='baptism';$rows=[];
if($tab==='baptism'&&mp_table($conn,'baptisms')){$cols=mp_cols($conn,'baptisms');$where=in_array('guardian_member_id',$cols,true)?'b.guardian_member_id=?':'b.member_id=?';$rows=mp_rows($conn,"SELECT b.baptism_no,b.candidate_name,b.baptism_type,b.baptism_date,b.status FROM baptisms b WHERE $where ORDER BY b.baptism_date DESC",'i',[$mid]);}elseif($tab==='sunday'&&mp_table($conn,'sunday_school_pupils')){$rows=mp_rows($conn,"SELECT p.pupil_no,CONCAT(p.full_name) pupil_name,c.class_name,p.parent_guardian,p.status FROM sunday_school_pupils p LEFT JOIN sunday_school_classes c ON c.id=p.class_id WHERE p.parent_member_id=? ORDER BY p.full_name",'i',[$mid]);}elseif($tab==='youth'&&mp_table($conn,'youth')){$cols=mp_cols($conn,'youth');$where=in_array('guardian_member_id',$cols,true)?'y.guardian_member_id=?':'y.member_id=?';$rows=mp_rows($conn,"SELECT y.youth_no,CONCAT(COALESCE(m.first_name,''),' ',COALESCE(m.last_name,'')) youth_name,y.status FROM youth y LEFT JOIN members m ON m.id=y.member_id WHERE $where ORDER BY youth_name",'i',[$mid]);}
$stats=[['label'=>'Linked Records','value'=>count($rows),'icon'=>'fa-children'],['label'=>'Active','value'=>count(array_filter($rows,fn($r)=>strtolower((string)($r['status']??''))==='active')),'icon'=>'fa-user-check'],['label'=>'Categories','value'=>count(array_unique(array_filter(array_column($rows,'baptism_type')))),'icon'=>'fa-tags']];
include __DIR__.'/../includes/sidebar.php';?><div class="main-content"><?php include __DIR__.'/../includes/topbar.php';?><div class="content-wrapper"><div class="card"><div class="card-header"><h3>My Children Records</h3></div><div class="card-body"><?php mp_tabs($tabs,$tab);mp_render_listing_page($tabs[$tab],'These records are limited to children linked to your member account.',$rows,$stats);?></div></div></div></div><?php mp_standard_styles();require_once __DIR__.'/../includes/footer.php';?>
